namespace ks{namespace{PanelBytePartialTest partialTest=nullptr;using T=PanelByteTask;using S=T::Stage;using K=T::Kind;using P=T::Port;struct Point{unsigned location,length;};Point point(const T&t){unsigned delta=t.kind()==K::DataWrite||t.kind()==K::DataRead?0x44:0;if(t.reading()){switch(t.stage()){case S::Hold:return{0x87e + delta,2};case S::ClearGate:return{0x880 + delta,2};case S::DisableGate:return{0x882 + delta,4};case S::SelectControl:return{0x886 + delta,2};case S::WriteControl:return{0x888 + delta,2};case S::EnableControl:return{0x88a + delta,2};case S::WriteEnable:return{0x88c + delta,2};case S::WaitFirst:return{0x88e + delta,2};case S::WaitSecond:return{0x890 + delta,2};case S::WaitThird:return{0x892 + delta,2};case S::WaitFourth:return{0x894 + delta,2};case S::Transfer:return{0x896 + delta,2};case S::RestoreControl:return{0x898 + delta,2};case S::WriteRestore:return{0x89a + delta,2};case S::SetGate:return{0x89c + delta,2};case S::RestoreGate:return{0x89e + delta,4};case S::RestoreHeld:return{0x8a2 + delta,2};case S::Finish:return{0x8a4 + delta,2};default:break;}}else{switch(t.stage()){case S::Hold:return{0x862 + delta,2};case S::SelectControl:return{0x864 + delta,2};case S::WriteControl:return{0x866 + delta,2};case S::EnableControl:return{0x868 + delta,2};case S::WriteEnable:return{0x86a + delta,2};case S::Transfer:return{0x86c + delta,2};case S::WaitFirst:return{0x86e + delta,2};case S::WaitSecond:return{0x870 + delta,2};case S::WaitThird:return{0x872 + delta,2};case S::WaitFourth:return{0x874 + delta,2};case S::RestoreControl:return{0x876 + delta,2};case S::WriteRestore:return{0x878 + delta,2};case S::RestoreHeld:return{0x87a + delta,2};case S::Finish:return{0x87c + delta,2};default:break;}} throw std::runtime_error("Invalid panel byte stage");}unsigned address(P p){return p==P::Gate?0xfffeb1:p==P::Control?0xffff62:0xffff61;}}
bool PanelByteCalls::step(ControllerCpu&h){using namespace controllerDetail;unsigned pc=unsigned(h.getPC());std::optional<Call>*selected=nullptr;for(auto&c:calls)if(c&&c->token-c->depth==h.getSP()){selected=&c;break;}if(pc==0x862||pc==0x87e||pc==0x8a6||pc==0x8c2){if(selected)throw std::runtime_error("Overlapping panel byte");for(auto&c:calls)if(!c){selected=&c;break;}if(!selected)throw std::runtime_error("Panel byte capacity");selected->emplace(pc==0x862?K::CommandWrite:pc==0x87e?K::CommandRead:pc==0x8a6?K::DataWrite:K::DataRead,h.getSP());++started;}if(!selected||point((**selected).task).location!=pc){if(partialTest&&partialTest(h)){++partialEntries;return true;}return false;}auto&t=(**selected).task;auto stage=t.stage();auto before=h.cycles;Boundary f(h,pc,point(t).length);auto&v=h.regs;auto store=[&](P p){auto at=address(p);return (at&1)&&h.lastwrite==int(at-1)?0u:1u;};auto cost=t.nextClocks(store);t.advanceBefore(cost,[&](T::Read r){return r==T::Read::Input?uint8_t(v[6].rl):uint8_t(h.read8(0xffff51));},[&](P p,uint8_t value){f.store8(address(p),int8_t(value));},store);switch(stage){case S::Hold:f.push(v[0].r);(**selected).depth+=2;break;case S::ClearGate:f.move(v[0].rl,0);break;case S::SelectControl:case S::RestoreControl:f.move(v[0].rl,t.control());break;case S::EnableControl:f.move(v[0].rl,t.control()+8);break;case S::Transfer:if(t.reading())f.move(v[6].rl,t.data());break;case S::SetGate:f.move(v[0].rl,-1);break;case S::RestoreHeld:f.pop(v[0].r);(**selected).depth-=2;break;case S::Finish:f.ret();h.pc=h.makepc(f.next);selected->reset();++completed;break;default:break;}if(stage!=S::Finish)h.pc=h.makepc(point(t).location);if(h.cycles-before!=cost)throw std::runtime_error("Panel byte clocks differ");return true;}}

